import{_ as t,o as a,c as e,a as n}from"./app.DkoUFz-u.js";const _=JSON.parse('{"title":"🛡️ 网络安全：OWASP CSRF 完全防护指南","description":"","frontmatter":{},"headers":[],"relativePath":"backend/security/owasp/csrf.md","filePath":"backend/security/owasp/csrf.md"}'),i={name:"backend/security/owasp/csrf.md"};function l(o,s,r,p,c,h){return a(),e("div",null,[...s[0]||(s[0]=[n(`<p>当然可以。这是一份为你整理的关于 CSRF（跨站请求伪造）攻击与防护的详细学习笔记。内容涵盖了从基本概念、攻击原理到具体的防御方案，并结合了 OWASP 的建议，希望能帮助你全面理解这个话题。</p><h1 id="🛡️-网络安全-owasp-csrf-完全防护指南" tabindex="-1">🛡️ 网络安全：OWASP CSRF 完全防护指南 <a class="header-anchor" href="#🛡️-网络安全-owasp-csrf-完全防护指南" aria-label="Permalink to &quot;🛡️ 网络安全：OWASP CSRF 完全防护指南&quot;">​</a></h1><h2 id="_1-csrf-攻击概述" tabindex="-1">1. CSRF 攻击概述 <a class="header-anchor" href="#_1-csrf-攻击概述" aria-label="Permalink to &quot;1. CSRF 攻击概述&quot;">​</a></h2><p><strong>CSRF（Cross-Site Request Forgery，跨站请求伪造）</strong> 是一种诱骗用户在<strong>已登录的Web应用</strong>上执行非本意操作的攻击方式。它利用的是<strong>网站对用户浏览器的信任</strong>。</p><h3 id="_1-1-攻击原理与条件" tabindex="-1">1.1 攻击原理与条件 <a class="header-anchor" href="#_1-1-攻击原理与条件" aria-label="Permalink to &quot;1.1 攻击原理与条件&quot;">​</a></h3><p>一次成功的 CSRF 攻击必须同时满足以下三个条件：</p><ol><li><strong>用户已登录目标网站</strong>：并持有有效的会话 Cookie。</li><li><strong>用户访问了恶意网站或页面</strong>：该页面包含伪造的请求。</li><li><strong>目标网站的接口没有做CSRF防护</strong>：无法区分合法请求和伪造请求。</li></ol><p>其核心原理是：<strong>浏览器会自动携带目标站点的Cookie发起请求</strong>。攻击者正是利用了这一机制，让用户在不知情的情况下，以他们的身份和权限执行操作。</p><p>为了更直观地理解攻击流程，下图展示了一次典型 CSRF 攻击的完整过程：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">flowchart TD</span></span>
<span class="line"><span class="__shiki_140thh">    A[用户登录受信任网站A] --&gt; B[网站A下发会话Cookie]</span></span>
<span class="line"><span class="__shiki_140thh">    B --&gt; C[用户未登出情况下&lt;br&gt;访问恶意网站B]</span></span>
<span class="line"><span class="__shiki_140thh">    C --&gt; D[网站B返回包含&lt;br&gt;伪造请求的页面]</span></span>
<span class="line"><span class="__shiki_140thh">    D --&gt; E[用户浏览器自动携带Cookie&lt;br&gt;向网站A发出伪造请求]</span></span>
<span class="line"><span class="__shiki_140thh">    E --&gt; F{网站A验证Cookie}</span></span>
<span class="line"><span class="__shiki_140thh">    F -- Cookie有效 --&gt; G[以用户权限执行操作&lt;br&gt;攻击完成]</span></span></code></pre></div><h3 id="_1-2-与-xss-的区别" tabindex="-1">1.2 与 XSS 的区别 <a class="header-anchor" href="#_1-2-与-xss-的区别" aria-label="Permalink to &quot;1.2 与 XSS 的区别&quot;">​</a></h3><p>这是一个常见的混淆点，它们的核心区别在于：</p><table tabindex="0"><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;">XSS（跨站脚本攻击）</th><th style="text-align:left;">CSRF（跨站请求伪造）</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>利用的信任</strong></td><td style="text-align:left;">利用<strong>用户对网站的信任</strong></td><td style="text-align:left;">利用<strong>网站对用户浏览器的信任</strong></td></tr><tr><td style="text-align:left;"><strong>攻击目标</strong></td><td style="text-align:left;">窃取用户数据（如Cookie、会话令牌），伪装用户</td><td style="text-align:left;">冒充用户执行操作（如转账、改密）</td></tr><tr><td style="text-align:left;"><strong>实现方式</strong></td><td style="text-align:left;">向页面<strong>注入并执行</strong>恶意脚本</td><td style="text-align:left;"><strong>伪造</strong>一个请求，诱使用户触发</td></tr><tr><td style="text-align:left;"><strong>权限来源</strong></td><td style="text-align:left;">直接盗取到用户的权限</td><td style="text-align:left;"><strong>借用</strong>用户的权限，攻击者并未持有权限</td></tr></tbody></table><h2 id="_2-csrf-攻击防御方案" tabindex="-1">2. CSRF 攻击防御方案 <a class="header-anchor" href="#_2-csrf-攻击防御方案" aria-label="Permalink to &quot;2. CSRF 攻击防御方案&quot;">​</a></h2><p>根据 OWASP 的建议，CSRF 防护的核心原则是：<strong>不要信任来自客户端的每一个请求，验证其来源和用户意图</strong>。</p><h3 id="_2-1-csrf-token-最常用且有效" tabindex="-1">2.1 CSRF Token（最常用且有效） <a class="header-anchor" href="#_2-1-csrf-token-最常用且有效" aria-label="Permalink to &quot;2.1 CSRF Token（最常用且有效）&quot;">​</a></h3><p>这是当前最主流、最有效的防御方案。</p><ul><li><strong>原理</strong>：在表单或请求中嵌入一个随机的、不可预测的 Token（令牌），服务器端验证该 Token 的有效性。攻击者无法预测或获取这个 Token，因此无法构造出合法的请求。</li><li><strong>实现细节</strong>： <ul><li>Token 需与用户会话（Session）关联。</li><li>Token 应具备随机性和不可预测性（如使用加密安全的随机数生成器）。</li><li>Token 应设置为一次性使用或短时间内有效。</li><li>确保 Token 不会通过任何途径泄漏（例如，在日志或 URL 中）。</li></ul></li></ul><p><strong>示例：在 Django 框架中使用 CSRF Token</strong> Django 内置了 CSRF 中间件，使用非常简单。</p><ol><li><strong>后端设置</strong>：确保 <code>django.middleware.csrf.CsrfViewMiddleware</code> 中间件已启用。</li><li><strong>模板（HTML）设置</strong>：在表单中插入 <code>{% csrf_token %}</code> 标签。</li></ol><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">&lt;</span><span class="__shiki_17hn0y">form</span><span class="__shiki_1t8gfj"> method</span><span class="__shiki_140thh">=</span><span class="__shiki_mdbnqw">&quot;post&quot;</span><span class="__shiki_140thh">&gt;</span></span>
<span class="line"><span class="__shiki_140thh">  {% csrf_token %} </span><span class="__shiki_21nrsd">&lt;!-- 这会被替换为一个隐藏的input字段 --&gt;</span></span>
<span class="line"><span class="__shiki_140thh">  &lt;</span><span class="__shiki_17hn0y">input</span><span class="__shiki_1t8gfj"> type</span><span class="__shiki_140thh">=</span><span class="__shiki_mdbnqw">&quot;text&quot;</span><span class="__shiki_1t8gfj"> name</span><span class="__shiki_140thh">=</span><span class="__shiki_mdbnqw">&quot;username&quot;</span><span class="__shiki_140thh">&gt;</span></span>
<span class="line"><span class="__shiki_140thh">  &lt;</span><span class="__shiki_17hn0y">input</span><span class="__shiki_1t8gfj"> type</span><span class="__shiki_140thh">=</span><span class="__shiki_mdbnqw">&quot;submit&quot;</span><span class="__shiki_1t8gfj"> value</span><span class="__shiki_140thh">=</span><span class="__shiki_mdbnqw">&quot;Submit&quot;</span><span class="__shiki_140thh">&gt;</span></span>
<span class="line"><span class="__shiki_140thh">&lt;/</span><span class="__shiki_17hn0y">form</span><span class="__shiki_140thh">&gt;</span></span></code></pre></div><ol start="3"><li><strong>Ajax 请求</strong>：需要从 Cookie 中读取 CSRF Token 并设置在请求头中。</li></ol><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">// 使用 jQuery</span></span>
<span class="line"><span class="__shiki_1itgoe">const</span><span class="__shiki_dzsirb"> csrftoken</span><span class="__shiki_1itgoe"> =</span><span class="__shiki_140thh"> document.</span><span class="__shiki_1t8gfj">querySelector</span><span class="__shiki_140thh">(</span><span class="__shiki_mdbnqw">&#39;[name=csrfmiddlewaretoken]&#39;</span><span class="__shiki_140thh">).value;</span></span>
<span class="line"><span class="__shiki_140thh">$.</span><span class="__shiki_1t8gfj">ajax</span><span class="__shiki_140thh">({</span></span>
<span class="line"><span class="__shiki_140thh">    url: </span><span class="__shiki_mdbnqw">&quot;/api/change_email/&quot;</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_140thh">    type: </span><span class="__shiki_mdbnqw">&quot;POST&quot;</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_140thh">    headers: { </span><span class="__shiki_mdbnqw">&#39;X-CSRFToken&#39;</span><span class="__shiki_140thh">: csrftoken },</span></span>
<span class="line"><span class="__shiki_140thh">    data: { new_email: </span><span class="__shiki_mdbnqw">&#39;user@example.com&#39;</span><span class="__shiki_140thh"> }</span></span>
<span class="line"><span class="__shiki_140thh">});</span></span></code></pre></div><h3 id="_2-2-samesite-cookie-属性-现代浏览器利器" tabindex="-1">2.2 SameSite Cookie 属性（现代浏览器利器） <a class="header-anchor" href="#_2-2-samesite-cookie-属性-现代浏览器利器" aria-label="Permalink to &quot;2.2 SameSite Cookie 属性（现代浏览器利器）&quot;">​</a></h3><p>这是一种由浏览器原生支持的、非常有效的防御方式。</p><ul><li><strong>原理</strong>：通过设置 Cookie 的 <code>SameSite</code> 属性，可以控制浏览器在跨站请求时是否发送此 Cookie。</li><li><strong>属性值</strong>： <ul><li><strong><code>Strict</code></strong>（最严格）：完全禁止第三方 Cookie。例如，如果用户在第三方网站点击链接，其 <code>Strict</code> 模式的 Cookie 不会被发送。</li><li><strong><code>Lax</code></strong>（宽松）：允许部分安全的跨站请求（如导航链接，GET 请求）携带 Cookie，但会阻止不安全的跨站 POST 请求等。这是目前许多站点默认推荐的配置。</li><li><strong><code>None</code></strong>：允许跨域携带 Cookie，但必须与 <code>Secure</code> 属性一同使用（即仅限 HTTPS）。</li></ul></li></ul><p><strong>示例：在 HTTP 响应头中设置</strong></p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_17hn0y">Set-Cookie</span><span class="__shiki_1itgoe">:</span><span class="__shiki_mdbnqw"> sessionid=xxxxx; SameSite=Lax; Secure</span></span></code></pre></div><h3 id="_2-3-验证请求来源" tabindex="-1">2.3 验证请求来源 <a class="header-anchor" href="#_2-3-验证请求来源" aria-label="Permalink to &quot;2.3 验证请求来源&quot;">​</a></h3><p>通过检查 HTTP 请求头中的 <code>Origin</code> 或 <code>Referer</code> 字段，来判断请求是否来自同源域名。</p><ul><li><strong><code>Origin</code></strong>：指明了请求的来源域名（仅包含域名信息），对于 POST 请求和跨域请求，浏览器通常会携带此头。</li><li><strong><code>Referer</code></strong>：包含了具体的请求来源页面完整路径（可能包含敏感信息，且存在被禁用的可能）。</li></ul><p><strong>注意</strong>：这种方法<strong>并非绝对可靠</strong>，因为 <code>Referer</code> 和 <code>Origin</code> 可以被伪造，或者在某些环境下（如浏览器隐私模式）可能缺失。通常作为辅助防御手段。</p><h3 id="_2-4-双重-cookie-验证" tabindex="-1">2.4 双重 Cookie 验证 <a class="header-anchor" href="#_2-4-双重-cookie-验证" aria-label="Permalink to &quot;2.4 双重 Cookie 验证&quot;">​</a></h3><ul><li><strong>原理</strong>：将 Cookie 中的某个值（如 Session ID），同时作为请求参数或自定义 Header 发送，服务器验证两者是否一致。</li><li><strong>优点</strong>：实现相对简单。</li><li><strong>缺点</strong>：如果网站存在 XSS 漏洞，攻击者可能读取到 Cookie 值，从而绕过此防御。</li></ul><h3 id="_2-5-关键操作二次验证" tabindex="-1">2.5 关键操作二次验证 <a class="header-anchor" href="#_2-5-关键操作二次验证" aria-label="Permalink to &quot;2.5 关键操作二次验证&quot;">​</a></h3><p>对于资金转移、密码修改等高风险操作，强制用户进行二次交互验证是一种非常有效的安全措施。</p><ul><li><strong>方式</strong>：要求用户重新输入密码、提供短信验证码、邮箱确认链接等。</li><li><strong>效果</strong>：即使 CSRF 攻击发生，攻击者也无法提供这些二次验证信息，从而确保操作的合法性。</li></ul><h2 id="_3-综合防御策略与最佳实践" tabindex="-1">3. 综合防御策略与最佳实践 <a class="header-anchor" href="#_3-综合防御策略与最佳实践" aria-label="Permalink to &quot;3. 综合防御策略与最佳实践&quot;">​</a></h2><p>在实际项目中，我们应采用纵深防御策略，结合多种方案。</p><ol><li><p><strong>首选方案：CSRF Token + SameSite Cookie</strong></p><ul><li>对于所有状态变更的请求（POST, PUT, DELETE, PATCH）使用 <strong>CSRF Token</strong> 作为主要防护手段。</li><li>为会话 Cookie 设置 <strong><code>SameSite=Lax</code> 或 <code>Strict</code></strong>，作为一道坚固的防线。</li></ul></li><li><p><strong>辅助增强</strong></p><ul><li><strong>验证 <code>Origin</code>/<code>Referer</code> 头</strong>：作为额外的校验层。</li><li><strong>关键操作增加二次验证</strong>：如修改密码、转账必须验证旧密码或短信验证码。</li></ul></li><li><p><strong>安全头配置</strong>：在 Web 服务器层面配置安全头，提供额外保护。</p><ul><li><strong><code>X-Frame-Options</code></strong>：防止页面被嵌入到 <code>&lt;iframe&gt;</code> 中，减少点击劫持风险。</li><li><strong><code>Content-Security-Policy</code></strong>：通过限制页面可以加载的资源来源，有效防止多种注入攻击。</li></ul></li></ol><h2 id="_4-csrf-防护检查清单" tabindex="-1">4. CSRF 防护检查清单 <a class="header-anchor" href="#_4-csrf-防护检查清单" aria-label="Permalink to &quot;4. CSRF 防护检查清单&quot;">​</a></h2><p>在开发或审计一个系统时，你可以使用以下清单来确保 CSRF 防护到位：</p><table tabindex="0"><thead><tr><th style="text-align:left;">类别</th><th style="text-align:left;">检查项</th><th style="text-align:left;">状态</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>核心防护</strong></td><td style="text-align:left;">✅ 所有表单和状态变更的 API 是否都使用了<strong>随机且不可预测的 CSRF Token</strong>？</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">✅ CSRF Token 是否在服务器端与用户会话<strong>正确绑定并验证</strong>？</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">✅ 会话 Cookie 是否已设置 <strong><code>SameSite=Lax</code> 或 <code>Strict</code></strong> 属性？</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>请求验证</strong></td><td style="text-align:left;">✅ 是否对敏感请求的 <code>Origin</code>/<code>Referer</code> 头进行了验证（如用作辅助验证）？</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">✅ 是否<strong>避免使用 GET 请求</strong>进行状态修改操作？</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>二次验证</strong></td><td style="text-align:left;">✅ 对于关键操作（如转账、改密）是否实施了<strong>二次验证</strong>（密码、短信等）？</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><strong>安全配置</strong></td><td style="text-align:left;">✅ 是否配置了 <code>X-Frame-Options</code> 和 <code>Content-Security-Policy</code> 等安全头？</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">✅ 系统依赖的框架和库是否保持最新，以避免已知漏洞？</td><td style="text-align:left;"></td></tr></tbody></table><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>CSRF 是一种利用网站对浏览器信任的经典攻击。防御的核心在于<strong>打破&quot;请求即自愿&quot;的假设</strong>，通过 CSRF Token、SameSite Cookie 等技术手段验证每一个敏感请求的真实意图。将这些防护措施融入到开发和部署的各个环节，是构建安全 Web 应用的关键一步。</p><blockquote><p><strong>重要提示</strong>：请注意，如果网站同时存在 XSS 漏洞，攻击者有可能窃取到 CSRF Token，从而使 Token 防护机制失效。因此，安全是一个整体工程，在做好 CSRF 防护的同时，也务必做好 XSS 等其他漏洞的防护工作。</p></blockquote>`,46)])])}const g=t(i,[["render",l]]);export{_ as __pageData,g as default};
